78:         ?? /\bexport\s+default\s*\{/.exec(text);
79:     if (!declaration) return {};
80:     const start = text.indexOf('{', declaration.index);
81:     let depth = 0;
82:     let quote = null;
83:     let escaped = false;
84:     let lineComment = false;
85:     let blockComment = false;
86:     for (let index = start; index < text.length; index++) {
87:         const char = text[index];
88:         const next = text[index + 1];
89:         if (lineComment) {
90:             if (char === '\n') lineComment = false;
91:             continue;
92:         }
93:         if (blockComment) {
94:             if (char === '*' && next === '/') {
95:                 blockComment = false;
96:                 index++;
97:             }
98:             continue;
99:         }
100:         if (quote) {
101:             if (escaped) {
102:                 escaped = false;
103:                 continue;
104:             }
105:             if (char === '\\') {
106:                 escaped = true;
107:                 continue;
108:             }
109:             if (char === quote) quote = null;
110:             continue;
111:         }
112:         if (char === "'" || char === '"' || char === '`') {
113:             quote = char;
114:             continue;
115:         }
116:         if (char === '/' && next === '/') {
117:             lineComment = true;
118:             index++;
119:             continue;
120:         }
121:         if (char === '/' && next === '*') {
122:             blockComment = true;
123:             index++;
124:             continue;
125:         }
126:         if (char === '{') depth++;
127:         else if (char === '}') {
128:             depth--;
129:             if (depth === 0) {
130:                 const raw = text.slice(start, index + 1).replace(/,\s*}/g, '}');
131:                 return JSON.parse(raw);
132:             }
