517: function walk(directory, output = []) {
518:     for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
519:         const full = path.join(directory, entry.name);
520:         if (entry.isDirectory()) walk(full, output);
521:         else output.push(full);
