534: function scanMonacoCalls(esmRoot) {
535:     const calls = [];
536:     const files = walk(esmRoot).filter(file => file.endsWith('.js'));
537:     const pattern = /\blocalize2?\s*\(\s*(?:'((?:[^'\\]|\\.)*)'|"((?:[^"\\]|\\.)*)")\s*,\s*(?:'((?:[^'\\]|\\.)*)'|"((?:[^"\\]|\\.)*)")/g;
538:     for (const file of files) {
539:         const source = fs.readFileSync(file, 'utf8');
540:         const module = path.relative(esmRoot, file).replace(/\\/g, '/').replace(/\.js$/, '');
541:         let match;
542:         while ((match = pattern.exec(source))) {
543:             calls.push({
544:                 module,
545:                 key: decodeString(match[1] ?? match[2]),
546:                 english: decodeString(match[3] ?? match[4]),
547:             });
548:         }
549:     }
550:     return calls;
