557: function addTranslation(map, module, key, translation, conflicts) {
558:     const previous = map[module]?.[key];
559:     if (previous !== undefined && previous !== translation) {
560:         conflicts.add(`${module}::${key}`);
561:         return false;
562:     }
563:     (map[module] ??= {})[key] = translation;
564:     return true;
565: }
