567: function sortMap(map) {
568:     const sorted = {};
569:     for (const module of Object.keys(map).sort()) {
570:         sorted[module] = {};
571:         for (const key of Object.keys(map[module]).sort()) sorted[module][key] = map[module][key];
572:     }
573:     return sorted;
574: }
