    "agentChat.accepted": "已接受",
    "agentChat.agent": "智能体",
---
// Generated by scripts/i18n/i18n.mjs for zh-Hant from VS Code 1.96.2
// and vscode-language-pack-zh-hant v1.96.2024121109. Community entries come from community/zh-Hant.ts.
const catalog: Record<string, string> = {
    "app.closeAll": "全部關閉",
    "app.closeOthers": "關閉其他",
---
import en from './messages/en'

/**
 * Native (Tauri) menu labels. The translations live in the shared catalogs;
 * this module lists the IDs the Rust menu uses and filters untranslated ones.
 */
export const MENU_KEYS = [
    'menu.noRecentFiles',
    'menu.clearRecent',
    'menu.openRecent',
    'menu.newTab',
    'menu.newWindow',
    'common.openEllipsis',
    'common.save',
    'common.saveAsEllipsis',
    'menu.closeTab',
    'menu.showServerLog',
    'menu.stopServer',
    'menu.restartServer',
    'menu.quit',
] as const

export function menuLabels(t: (key: string) => string): Record<string, string> {
    const labels: Record<string, string> = {}
    for (const id of MENU_KEYS) {
        const english = en[id] ?? id
        const translated = t(id)
        if (translated !== english) labels[english] = translated
    }
    return labels
}
---
/** Human-editable community translations. */
export interface CommunityCatalog {
    ui: Record<string, string>
    monaco: Record<string, string>
}

