// Report first: it is the default rendering everywhere else, so it reads as the one to
// reach for. A form and a code listing have no meaningful Word form, hence `word: false`.
const EXPORT_GROUPS: { variant: ExportVariant; label: string; detail: string; word: boolean }[] = [
  {
    variant: 'report',
    label: 'app.report',
    detail: '#pre hidden, #post shown, entered #UI values applied.',
    word: true,
  },
  {
    variant: 'preview',
    label: 'common.preview',
    detail: 'What the results pane shows: #pre and #post, and the same #UI values it renders.',
    word: true,
  },
  {
    variant: 'input',
    label: 'Input form',
    detail: 'The #UI form itself, #post hidden. Exported controls are static.',
    word: false,
  },
  {
    variant: 'unwrapped',
    label: 'app.unwrapped',
    detail: 'The source listing with macros and includes resolved.',
    word: false,
  },
]

const props = withDefaults(defineProps<{
  plots: PlotSummary[]
  loading: boolean
  versionConfig?: VersionConfig
  isCompiled?: boolean
  writeMode?: WriteMode
  writeResult?: { ok: boolean; message: string } | null
}>(), {
  versionConfig: () => ({ ...DEFAULT_VERSION_CONFIG }),
  isCompiled: false,
  writeMode: 'reportOnly',
  writeResult: null,
})

// A compiled worksheet has no source: Preview and Unwrapped both render from it.
const SOURCE_EXPORT_VARIANTS: ExportVariant[] = ['preview', 'unwrapped']
const visibleExportGroups = computed(() =>
  props.isCompiled
    ? EXPORT_GROUPS.filter(g => !SOURCE_EXPORT_VARIANTS.includes(g.variant))
    : EXPORT_GROUPS
)

// Both entries are hidden for a compiled worksheet, and the portable package also in the
// browser, so the whole section goes when nothing would be left in it.
const showPortable = computed(() => !props.isCompiled)

const localWriteMode = ref<WriteMode>(props.writeMode)
watch(() => props.writeMode, v => { localWriteMode.value = v })

const writeModeDetail = computed(() =>
  WRITE_MODE_OPTIONS.map(o => `${t(o.label)} — ${t(o.detail)}`).join('\n')
)

